func topKFrequent(words []string, k int) []string {
	// 处理边界
	if len(words) < 1 {
		return words
	}
	type wordInfo struct {
		word  string
		times int
	}
	occo := map[string]int{}
	for _, v := range words {
		occo[v]++
	}
	sortList := []wordInfo{}
	for k, v := range occo {
		sortList = append(sortList, wordInfo{k, v})
	}
	// 排序
	sort.Slice(sortList, func(i, j int) bool {
		if sortList[i].times == sortList[j].times {
			return sortList[i].word < sortList[j].word
		}
		return sortList[i].times>sortList[j].times

	})
	minNum := func(x, y int) int {
		if x <= y {
			return x
		}
		return y
	}(len(sortList), k)
	ans := []string{}
	for i := 0; i < minNum; i++ {
		ans = append(ans, sortList[i].word)
	}
	return ans
}
